import { Sequelize, DataTypes, QueryTypes } from 'sequelize';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';
import config from './config';
import logger from './logger';

// Get directory name in ES module
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

dotenv.config({ path: path.join(__dirname, '../../.env') });

const sequelize = new Sequelize(
  config.db.database,
  config.db.username,
  config.db.password,
  {
    host: config.db.host,
    port: config.db.port,
    dialect: 'postgres',
    logging: false,
    define: {
      timestamps: true,
      underscored: true,
      freezeTableName: true,
      paranoid: true,
      createdAt: 'created_at',
      updatedAt: 'updated_at',
      deletedAt: 'deleted_at'
    },
    pool: {
      max: 5,
      min: 0,
      acquire: 30000,
      idle: 10000
    },
    dialectOptions: process.env.NODE_ENV === 'production' ? {
      ssl: {
        require: true,
        rejectUnauthorized: false
      }
    } : {}
  }
);

async function testConnection() {
  try {
    logger.info('Đang kết nối đến database...', {
      host: config.db.host,
      port: config.db.port,
      database: config.db.database,
      username: config.db.username
    });
    
    await sequelize.authenticate();
    
    // Test thực thi một query đơn giản
    const [result] = await sequelize.query('SELECT 1+1 AS result', { type: QueryTypes.SELECT });
    logger.info('Kết nối database thành công', { result });
    
    return true;
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    const errorStack = error instanceof Error ? error.stack : undefined;
    
    logger.error('Lỗi kết nối database:', {
      message: errorMessage,
      stack: errorStack,
      config: {
        host: config.db.host,
        port: config.db.port,
        database: config.db.database,
        username: config.db.username
      }
    });
    
    if (error instanceof Error) {
      throw error;
    }
    throw new Error(errorMessage);
  }
}

async function closeConnection() {
  await sequelize.close();
  return true;
}

// Xử lý sự kiện đóng kết nối
process.on('SIGINT', async () => {
  logger.info('Nhận được tín hiệu SIGINT. Đang đóng kết nối database...');
  await closeConnection();
  process.exit(0);
});

process.on('SIGTERM', async () => {
  logger.info('Nhận được tín hiệu SIGTERM. Đang đóng kết nối database...');
  await closeConnection();
  process.exit(0);
});

// Xử lý các lỗi chưa được bắt
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection tại:', promise, 'Lý do:', reason);
});

process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  process.exit(1);
});

export { sequelize, DataTypes };

export default {
  query: sequelize.query.bind(sequelize),
  transaction: sequelize.transaction.bind(sequelize),
  authenticate: sequelize.authenticate.bind(sequelize),
  sync: sequelize.sync.bind(sequelize),
  init: testConnection,
  close: closeConnection
};
